// Zero-Trust Vault v2.0.0 — popup UI controller.
//
// Security changes from v1:
//   - TOTP codes are generated by the native host (requires Hello), never computed here.
//   - TOTP secrets are never encoded in the display label or visible in the popup.
//   - "Never" session timeout removed — max is 1 hour.
//   - Clipboard copy disabled by default; secret copy requires native host v2.
//   - Debug bypass banner removed — bypass code is absent in release builds.
//   - Security Health Dashboard added.

const $ = (id) => document.getElementById(id);

const ui = {
  lockBadge:         $("lockBadge"),
  healthToggle:      $("healthToggle"),
  healthPanel:       $("healthPanel"),
  healthItems:       $("healthItems"),
  settingsToggle:    $("settingsToggle"),
  settingsPanel:     $("settingsPanel"),
  modeText:          $("modeText"),
  convenienceToggle: $("convenienceToggle"),
  clipboardToggle:   $("clipboardToggle"),
  autoPromptToggle:  $("autoPromptToggle"),
  autoPromptRow:     $("autoPromptRow"),
  origin:            $("origin"),
  alerts:            $("alerts"),
  unlockBtn:         $("unlockBtn"),
  lockBtn:           $("lockBtn"),
  accounts:          $("accounts"),
  searchRow:         $("searchRow"),
  searchInput:       $("searchInput"),
  accountList:       $("accountList"),
  addSection:        $("addSection"),
  toggleAdd:         $("toggleAdd"),
  addForm:           $("addForm"),
  addUser:           $("addUser"),
  addPass:           $("addPass"),
  genPassBtn:        $("genPassBtn"),
  revealPassBtn:     $("revealPassBtn"),
  strengthRow:       $("strengthRow"),
  strengthBar:       $("strengthBar"),
  strengthLabel:     $("strengthLabel"),
  addLabel:          $("addLabel"),
  addTotp:           $("addTotp"),
  saveBtn:           $("saveBtn"),
  status:            $("status"),
  timeoutSelect:     $("timeoutSelect"),
};

let ctx = { origin: null, hasLogin: false };
let sec = { convenienceEnabled: false, clipboardCopyEnabled: false, site: { autoPrompt: false }, isHighRisk: false };
let currentAccounts = [];

// ---- Messaging --------------------------------------------------------------

function send(msg) {
  return new Promise((resolve, reject) => {
    if (!globalThis.chrome?.runtime?.sendMessage) return reject(new Error("not running as extension"));
    chrome.runtime.sendMessage(msg, (r) => {
      const e = chrome.runtime.lastError;
      if (e) return reject(new Error(e.message));
      if (r?.ok === false && r?.error) return reject(new Error(r.error));
      resolve(r);
    });
  });
}

// ---- UI helpers -------------------------------------------------------------

function setStatus(text, kind = "") {
  ui.status.textContent = text || "";
  ui.status.className   = `status ${kind}`.trim();
}

function setLocked(locked) {
  ui.lockBadge.textContent = locked ? "LOCKED" : "UNLOCKED";
  ui.lockBadge.className   = `badge ${locked ? "locked" : "unlocked"}`;
  ui.unlockBtn.classList.toggle("hidden", !locked);
  ui.lockBtn.classList.toggle("hidden", locked);
  ui.accounts.classList.toggle("hidden", locked);
  ui.addSection.classList.toggle("hidden", locked);
}

function addAlert(text, kind = "info") {
  const div = document.createElement("div");
  div.className   = `alert ${kind}`;
  div.textContent = text;
  ui.alerts.appendChild(div);
}

function refreshSettingsUi() {
  ui.modeText.textContent        = sec.convenienceEnabled ? "Ultra Security + Detector" : "Ultra Security Mode";
  ui.convenienceToggle.checked   = !!sec.convenienceEnabled;
  ui.clipboardToggle.checked     = sec.clipboardCopyEnabled === true;
  ui.autoPromptToggle.checked    = !!sec.site?.autoPrompt;
  const autoPromptBlocked = !sec.convenienceEnabled || !ctx?.origin || ctx?.isHttp || ctx?.isIdn || sec?.isHighRisk;
  ui.autoPromptToggle.disabled   = autoPromptBlocked;
  ui.autoPromptRow.style.opacity = autoPromptBlocked ? "0.45" : "";
}

// ---- Label helpers (backward compat only — v2 stores TOTP in native host) ---
//
// Old format: {"_z":1,"l":"label","t":"BASE32SECRET"} — tells us hasTotp = true
// New format: plain label string — TOTP is in native host encrypted payload
// We parse old format only to detect the hasTotp flag for display.
// We NEVER compute TOTP codes from the secret here.

function parseLabel(raw) {
  if (!raw) return { label: "", hasTotp: false };
  try {
    const o = JSON.parse(raw);
    if (o?._z === 1) return { label: o.l || "", hasTotp: !!(o.t) };
  } catch {}
  return { label: raw, hasTotp: false };
}

// ---- Password generator + strength ------------------------------------------

function generatePassword(length = 24) {
  const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*-_=+?";
  const limit = 256 - (256 % chars.length);
  const out   = [];
  while (out.length < length) {
    const buf = new Uint8Array(length * 2);
    crypto.getRandomValues(buf);
    for (const b of buf) {
      if (b < limit && out.length < length) out.push(chars[b % chars.length]);
    }
  }
  return out.join("");
}

function passwordStrength(pw) {
  if (!pw) return null;
  const len   = pw.length;
  const types = [/[a-z]/, /[A-Z]/, /[0-9]/, /[^a-zA-Z0-9]/].filter(r => r.test(pw)).length;
  let score;
  if      (len < 8)               score = 1;
  else if (len < 12 || types < 2) score = 2;
  else if (len < 16 || types < 3) score = 3;
  else                             score = 4;
  const labels = ["", "Weak", "Fair", "Good", "Strong"];
  const colors = ["", "#f87171", "#fbbf24", "#34d399", "#5b8cff"];
  const widths  = ["", "25%", "50%", "75%", "100%"];
  return { score, label: labels[score], color: colors[score], width: widths[score] };
}

function updateStrength(pw) {
  const s = passwordStrength(pw);
  if (!s || !pw) { ui.strengthRow.classList.add("hidden"); return; }
  ui.strengthRow.classList.remove("hidden");
  ui.strengthBar.style.width      = s.width;
  ui.strengthBar.style.background = s.color;
  ui.strengthLabel.textContent    = s.label;
  ui.strengthLabel.style.color    = s.color;
}

// ---- Security Health Dashboard ----------------------------------------------

function makeHealthItem(icon, label, value, kind) {
  const row = document.createElement("div");
  row.className = "health-item";
  const ic  = document.createElement("span"); ic.className  = "health-icon";  ic.textContent = icon;
  const lbl = document.createElement("span"); lbl.className = "health-label"; lbl.textContent = label;
  const val = document.createElement("span"); val.className = `health-value ${kind}`; val.textContent = value;
  row.append(ic, lbl, val);
  return row;
}

async function refreshHealthPanel() {
  ui.healthItems.innerHTML = "";
  try {
    const r = await send({ type: "securityHealthCheck" });
    const h = r?.health || {};

    const items = [];

    // Extension integrity (rich object, with legacy boolean fallback)
    const ig = h.extensionIntegrity || null;
    if (ig) {
      if (ig.status === "passed")
        items.push(["✅", "Integrity check", `Passed (${ig.checkedFilesCount} files)`, "ok"]);
      else if (ig.status === "failed")
        items.push(["❌", "Integrity check",
          `FAILED: ${ig.failingFilesCount}/${ig.checkedFilesCount} — ${(ig.failingFileNames||[]).join(", ")}`, "err"]);
      else if (ig.status === "skipped")
        items.push(["⚠️", "Integrity check", "Not stamped (dev build)", "warn"]);
      else
        items.push(["⚠️", "Integrity check", "Not run yet", "warn"]);
      if (ig.failingFilesCount > 0)
        items.push(["❌", "Failing files", (ig.failingFileNames||[]).join(", ") || "(unknown)", "err"]);
      if (ig.lastCheckedAt)
        items.push(["ℹ️", "Last integrity check", new Date(ig.lastCheckedAt).toLocaleString(), "ok"]);
    } else if (h.extensionIntegrityPassed === true) {
      items.push(["✅", "Integrity check", "Passed", "ok"]);
    } else if (h.extensionIntegrityPassed === false) {
      items.push(["❌", "Integrity check", "FAILED — files tampered?", "err"]);
    } else {
      items.push(["⚠️", "Integrity check", "Not run (dev build)", "warn"]);
    }

    // Extension package mode — never claim a store package we cannot prove.
    const mode = h.packageMode || (h.extensionUnpacked ? "unpacked_developer_mode" : "packed_unsigned");
    if (mode === "unpacked_developer_mode")
      items.push(["⚠️", "Package mode", "Unpacked developer mode — not a store package", "warn"]);
    else if (mode === "store_managed_unverified")
      items.push(["⚠️", "Package mode", "Store-managed — store identity not verified here", "warn"]);
    else if (mode === "packed_unsigned")
      items.push(["⚠️", "Package mode", "Packed, unsigned", "warn"]);
    else
      items.push(["⚠️", "Package mode", `${mode} — not verified as production store package`, "warn"]);

    // Native host connection (if we got health data, host is running)
    items.push(["✅", "Native host", "Connected", "ok"]);

    // Vault schema
    if (h.schemaVersion)
      items.push(["✅", "Vault schema", `v${h.schemaVersion}`, h.schemaVersion >= 3 ? "ok" : "warn"]);

    // TOTP
    items.push(["✅", "TOTP protection", "Native host (never in popup)", "ok"]);

    // Session timeout
    const t = h.sessionTimeoutMinutes;
    if (t === 0)
      items.push(["✅", "Auto-lock", "Immediate", "ok"]);
    else if (t > 0 && t <= 15)
      items.push(["✅", "Auto-lock", `${t} min`, "ok"]);
    else if (t > 15 && t <= 60)
      items.push(["⚠️", "Auto-lock", `${t} min`, "warn"]);
    else
      items.push(["❌", "Auto-lock", "Never — not permitted", "err"]);

    // Clipboard
    if (h.clipboardCopyEnabled)
      items.push(["⚠️", "Clipboard copy", "Enabled — malware risk", "warn"]);
    else
      items.push(["✅", "Clipboard copy", "Disabled (fill only)", "ok"]);

    // Recovery kit
    if (h.recoveryKitStatus === "verified")
      items.push(["✅", "Recovery kit", "Created & verified", "ok"]);
    else if (h.recoveryKitStatus === "created")
      items.push(["⚠️", "Recovery kit", "Created, not verified", "warn"]);
    else
      items.push(["❌", "Recovery kit", "Not created — hardware failure = total loss", "err"]);

    // Last backup
    if (h.lastBackupTime) {
      const ago = Math.round((Date.now() - new Date(h.lastBackupTime).getTime()) / 3600000);
      items.push(["✅", "Last backup", ago < 24 ? `${ago}h ago` : `${Math.round(ago/24)}d ago`, ago < 48 ? "ok" : "warn"]);
    } else {
      items.push(["⚠️", "Last backup", "Unknown", "warn"]);
    }

    // USB backup
    if (h.usbBackupEnabled)
      items.push(["⚠️", "USB auto-backup", "Enabled — opt-in verified", "warn"]);
    else
      items.push(["✅", "USB auto-backup", "Off (opt-in with -IncludeUsb)", "ok"]);

    // Device count
    if (h.deviceCount !== undefined)
      items.push(["✅", "Enrolled devices", String(h.deviceCount), "ok"]);

    // Sync status — honest classification, never a false "production".
    // Until the full MeshSync acceptance set passes, this is "Partial MeshSync".
    const syncStatus = h.syncStatus || "Partial MeshSync — not production sync";
    items.push(["⚠️", "Sync", syncStatus, "warn"]);

    // External audit — honest until a real third-party report exists.
    const audit = h.externalAuditStatus || "Audit-ready only — no external audit";
    items.push(["⚠️", "External audit", audit, "warn"]);

    // Debug logging status (release builds must be a no-op)
    if (h.diagnosticLogging === "enabled")
      items.push(["❌", "Debug logging", "ENABLED — not a release build", "err"]);
    else
      items.push(["✅", "Debug logging", "Disabled (release-safe)", "ok"]);

    // HTTP/IDN blocked
    items.push(["✅", "HTTP credential release", "Blocked", "ok"]);
    items.push(["✅", "IDN/punycode", "Blocked", "ok"]);
    items.push(["✅", "Auto-submit", "Disabled", "ok"]);

    for (const [icon, label, value, kind] of items) {
      ui.healthItems.appendChild(makeHealthItem(icon, label, value, kind));
    }

    // Warnings section
    const warnings = [];
    if (ig && ig.status === "failed")
      warnings.push("⛔ Integrity FAILED on: " + (ig.failingFileNames||[]).join(", ") +
                    ". Run tools/update-extension-hashes.ps1 after legitimate source changes, then reload. Secret operations are blocked.");
    if (h.extensionUnpacked)         warnings.push("⚠ Unpacked extension: not production-secure.");
    if (!h.recoveryKitStatus || h.recoveryKitStatus === "none")
                                      warnings.push("⚠ Recovery kit not created: hardware failure can destroy vault access.");
    if (h.clipboardCopyEnabled)       warnings.push("⚠ Clipboard copy enabled: malware can read copied secrets.");
    if (h.sessionTimeoutMinutes < 0)  warnings.push("⚠ Never timeout not permitted in production security mode.");
    if (h.schemaVersion < 3)          warnings.push("ℹ Vault schema v2 — upgrade native host to v2 for full v3 schema.");

    if (warnings.length > 0) {
      const sep = document.createElement("div");
      sep.style.cssText = "margin-top:6px;padding-top:6px;border-top:1px solid var(--border);display:grid;gap:4px;";
      for (const w of warnings) {
        const d = document.createElement("div");
        d.style.cssText = "font-size:11px;color:var(--warn);line-height:1.4;";
        d.textContent = w;
        sep.appendChild(d);
      }
      ui.healthItems.appendChild(sep);
    }

  } catch (e) {
    const err = makeHealthItem("❌", "Health check failed", e.message.slice(0, 60), "err");
    ui.healthItems.appendChild(err);
  }
}

// ---- Account list rendering -------------------------------------------------

function renderAccounts(accounts) {
  currentAccounts = accounts || [];
  ui.accountList.innerHTML = "";
  ui.searchInput.value     = "";
  ui.searchRow.classList.toggle("hidden", currentAccounts.length < 2);

  if (currentAccounts.length === 0) {
    const li  = document.createElement("li");
    const msg = document.createElement("span");
    msg.className   = "acc-empty";
    msg.textContent = "No saved accounts for this exact origin";
    li.appendChild(msg);
    ui.accountList.appendChild(li);
    return;
  }

  for (const a of currentAccounts) {
    ui.accountList.appendChild(buildAccountItem(a));
  }
}

function buildAccountItem(a) {
  const parsed      = parseLabel(a.label || a.displayLabel || "");
  const hasTotp     = parsed.hasTotp || !!a.hasTotp;
  const displayName = a.usernameOrEmail || parsed.label || ("Account " + a.credentialId.slice(0, 8));

  const li = document.createElement("li");

  // ── Main info ──────────────────────────────────────────────────────────────
  const main = document.createElement("div");
  main.className = "acc-main";

  const userEl = document.createElement("div");
  userEl.className   = "acc-user";
  userEl.textContent = displayName;
  userEl.title       = parsed.label ? `${displayName}  ·  ${parsed.label}` : displayName;

  const subEl = document.createElement("div");
  subEl.className   = "acc-sub";
  subEl.textContent = hasTotp
    ? "Password hidden · fill requires Hello  ·  2FA configured"
    : "Password hidden · fill requires Hello";

  main.append(userEl, subEl);
  li.appendChild(main);

  // ── TOTP row — click "Get" to request code from native host (requires Hello) ─
  if (hasTotp) {
    const totpRow = document.createElement("div");
    totpRow.className = "acc-totp";

    const lbl2fa = document.createElement("span");
    lbl2fa.className   = "totp-label";
    lbl2fa.textContent = "2FA";

    const codeEl = document.createElement("span");
    codeEl.className   = "totp-code";
    codeEl.textContent = "••• •••";

    const barWrap = document.createElement("div");
    barWrap.className = "totp-progress-wrap totp-hidden";
    const barFill = document.createElement("div");
    barFill.className = "totp-progress";
    barWrap.appendChild(barFill);

    const timerEl = document.createElement("span");
    timerEl.className = "totp-timer totp-hidden";

    const getBtn = document.createElement("button");
    getBtn.className   = "totp-get-btn";
    getBtn.textContent = "Get";
    getBtn.title       = "Retrieve 2FA code from native host (requires Windows Hello)";

    let countdownId = null;
    const showCode = (code, secondsLeft) => {
      codeEl.textContent = code.slice(0, 3) + " " + code.slice(3);
      getBtn.classList.add("totp-hidden");
      barWrap.classList.remove("totp-hidden");
      timerEl.classList.remove("totp-hidden");
      let secs = secondsLeft;
      const tick = () => {
        timerEl.textContent = secs + "s";
        const pct   = (secs / 30) * 100;
        const color = secs <= 5 ? "var(--danger)" : secs <= 10 ? "var(--warn)" : "var(--accent)";
        barFill.style.width           = pct + "%";
        barFill.style.backgroundColor = color;
        timerEl.style.color = secs <= 5 ? "var(--danger)" : secs <= 10 ? "var(--warn)" : "var(--muted)";
        if (--secs < 0) {
          clearInterval(countdownId);
          countdownId = null;
          codeEl.textContent = "••• •••";
          getBtn.classList.remove("totp-hidden");
          barWrap.classList.add("totp-hidden");
          timerEl.classList.add("totp-hidden");
        }
      };
      tick();
      if (countdownId) clearInterval(countdownId);
      countdownId = setInterval(tick, 1000);
    };

    getBtn.addEventListener("click", async () => {
      getBtn.disabled = true;
      setStatus("Approve Windows Hello to get 2FA code…");
      try {
        const r = await send({ type: "generateTotp", credentialId: a.credentialId });
        if (r?.code) {
          showCode(r.code, r.secondsRemaining ?? 29);
          setStatus(`2FA code retrieved. Expires in ${r.secondsRemaining ?? 29}s.`, "ok");
        } else {
          setStatus("2FA generation failed.", "err");
        }
      } catch (e) {
        setStatus("2FA: " + e.message, "err");
      } finally {
        getBtn.disabled = false;
      }
    });

    totpRow.append(lbl2fa, codeEl, barWrap, timerEl, getBtn);
    li.appendChild(totpRow);
  }

  // ── Inline edit form (hidden by default) ───────────────────────────────────
  const editForm = document.createElement("div");
  editForm.className = "edit-form hidden";

  const editUser = document.createElement("input");
  editUser.type = "text"; editUser.placeholder = "username or email";
  editUser.autocomplete = "off"; editUser.value = a.usernameOrEmail || "";

  const editPassRow = document.createElement("div");
  editPassRow.className = "pass-row";

  const editPass = document.createElement("input");
  editPass.type = "password"; editPass.placeholder = "new password (required to save)";
  editPass.autocomplete = "off";

  const editGenBtn = document.createElement("button");
  editGenBtn.type = "button"; editGenBtn.className = "icon-btn";
  editGenBtn.title = "Generate strong password"; editGenBtn.textContent = "⟳";

  const editRevealBtn = document.createElement("button");
  editRevealBtn.type = "button"; editRevealBtn.className = "icon-btn";
  editRevealBtn.title = "Show / hide"; editRevealBtn.textContent = "👁";
  editRevealBtn.addEventListener("click", () => {
    if (editPass.type === "password") { editPass.type = "text"; editRevealBtn.textContent = "🙈"; }
    else                              { editPass.type = "password"; editRevealBtn.textContent = "👁"; }
  });

  editPassRow.append(editPass, editGenBtn, editRevealBtn);

  const editStrRow   = document.createElement("div"); editStrRow.className = "strength-row hidden";
  const editStrTrack = document.createElement("div"); editStrTrack.className = "strength-track";
  const editStrBar   = document.createElement("div"); editStrBar.className = "strength-fill";
  const editStrLbl   = document.createElement("span"); editStrLbl.className = "strength-label";
  editStrTrack.appendChild(editStrBar); editStrRow.append(editStrTrack, editStrLbl);

  const refreshEditStrength = (pw) => {
    const s = passwordStrength(pw);
    if (!s || !pw) { editStrRow.classList.add("hidden"); return; }
    editStrRow.classList.remove("hidden");
    editStrBar.style.width = s.width; editStrBar.style.background = s.color;
    editStrLbl.textContent = s.label; editStrLbl.style.color = s.color;
  };
  editPass.addEventListener("input", () => refreshEditStrength(editPass.value));
  editGenBtn.addEventListener("click", () => {
    const pw = generatePassword(24);
    editPass.type = "text"; editRevealBtn.textContent = "🙈";
    editPass.value = pw; refreshEditStrength(pw);
    setStatus("Strong 24-character password generated.", "ok");
  });

  const editTotp = document.createElement("input");
  editTotp.type = "text"; editTotp.placeholder = "2FA secret (leave blank to keep current)";
  editTotp.autocomplete = "off";

  const editLabel = document.createElement("input");
  editLabel.type = "text"; editLabel.placeholder = "label (optional)";
  editLabel.autocomplete = "off"; editLabel.value = parsed.label || "";

  const editBtns   = document.createElement("div"); editBtns.className = "edit-btns";
  const editSave   = document.createElement("button"); editSave.className = "primary"; editSave.textContent = "Update  (requires Hello)";
  const editCancel = document.createElement("button"); editCancel.className = "ghost"; editCancel.textContent = "Cancel";

  editCancel.addEventListener("click", () => {
    editForm.classList.add("hidden");
    editToggleBtn.textContent = "✏";
  });
  editSave.addEventListener("click", () =>
    doUpdate(a, editUser, editPass, editTotp, editLabel, editForm, editSave, editCancel));

  editBtns.append(editSave, editCancel);
  editForm.append(editUser, editPassRow, editStrRow, editTotp, editLabel, editBtns);
  li.appendChild(editForm);

  // ── Action buttons ─────────────────────────────────────────────────────────
  const actions = document.createElement("div");
  actions.className = "acc-actions";

  const copyBtn = document.createElement("button");
  copyBtn.className = "ghost copy-btn"; copyBtn.title = "Copy username"; copyBtn.textContent = "⎘";
  copyBtn.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(displayName);
      const prev = copyBtn.textContent; copyBtn.textContent = "✓";
      setTimeout(() => { copyBtn.textContent = prev; }, 1500);
    } catch { setStatus("Copy not available in this context.", "err"); }
  });

  const fillBtn = document.createElement("button");
  fillBtn.className = "primary"; fillBtn.textContent = "Fill ▶";
  fillBtn.title = "Requires a fresh Windows Hello approval";
  fillBtn.addEventListener("click", () => doFill(a.credentialId, fillBtn, li));

  const editToggleBtn = document.createElement("button");
  editToggleBtn.className = "icon-btn"; editToggleBtn.textContent = "✏";
  editToggleBtn.title = "Edit this credential";
  editToggleBtn.addEventListener("click", () => {
    const nowHidden = editForm.classList.toggle("hidden");
    editToggleBtn.textContent = nowHidden ? "✏" : "✕";
    if (!nowHidden) editUser.focus();
  });

  const delBtn = document.createElement("button");
  delBtn.className = "danger-ghost"; delBtn.textContent = "🗑"; delBtn.title = "Delete this credential";
  let confirmTimer = null;
  delBtn.addEventListener("click", () => {
    if (delBtn.dataset.confirming) {
      clearTimeout(confirmTimer); delete delBtn.dataset.confirming;
      doDelete(a.credentialId, fillBtn, delBtn, li);
      return;
    }
    delBtn.dataset.confirming = "1"; delBtn.textContent = "Sure?"; delBtn.className = "confirm-delete";
    confirmTimer = setTimeout(() => {
      delete delBtn.dataset.confirming; delBtn.textContent = "🗑"; delBtn.className = "danger-ghost";
    }, 4000);
  });

  actions.append(copyBtn, fillBtn, editToggleBtn, delBtn);
  li.appendChild(actions);
  return li;
}

// ---- Actions ----------------------------------------------------------------

async function timeoutStatusText() {
  try {
    const r = await send({ type: "getSessionTimeout" });
    if (!r) return "";
    const t = r.sessionTimeoutMinutes;
    if (t === 0) return "Locks immediately when you close this popup.";
    if (r.locksAt) {
      const mins = Math.max(1, Math.round((r.locksAt - Date.now()) / 60000));
      return `Auto-locks in ${mins} min.`;
    }
    return `Auto-locks ${t} min after closing.`;
  } catch { return ""; }
}

async function tryUnlock(statusMsg) {
  setStatus(statusMsg || "Waiting for Windows Hello…");
  ui.unlockBtn.disabled = true;
  try {
    const r = await send({ type: "unlock" });
    setLocked(false);
    renderAccounts(r.accounts);
    const tpmInfo  = r.presenceMode ? ` · ${r.presenceMode}` : "";
    const timeInfo = await timeoutStatusText();
    setStatus(`Unlocked${tpmInfo}. Fresh Hello per fill. ${timeInfo}`, "ok");
    return true;
  } catch (e) {
    setStatus("Windows Hello: " + e.message, "err");
    return false;
  } finally {
    ui.unlockBtn.disabled = false;
  }
}

async function doFill(credentialId, fillBtn, li) {
  fillBtn.disabled = true;
  setStatus("Approve Windows Hello to release this credential…");
  try {
    await send({ type: "fill", credentialId });
    setStatus("Filled ✓  Click the Sign in button on the page.", "ok");
  } catch (e) {
    setStatus("Fill blocked: " + e.message, "err");
  } finally {
    fillBtn.disabled = false;
  }
}

async function doDelete(credentialId, fillBtn, delBtn, li) {
  fillBtn.disabled = true; delBtn.disabled = true;
  setStatus("Deleting…");
  try {
    await send({ type: "delete", credentialId });
    li.style.transition = "opacity .2s"; li.style.opacity = "0";
    setTimeout(() => {
      li.remove();
      if (!ui.accountList.querySelector("li:not([style*='opacity: 0'])")) {
        const empty = document.createElement("li");
        const msg   = document.createElement("span");
        msg.className = "acc-empty"; msg.textContent = "No saved accounts for this exact origin";
        empty.appendChild(msg); ui.accountList.appendChild(empty);
      }
      currentAccounts = currentAccounts.filter(a => a.credentialId !== credentialId);
      ui.searchRow.classList.toggle("hidden", currentAccounts.length < 2);
    }, 200);
    setStatus("Credential deleted.", "ok");
  } catch (e) {
    delBtn.textContent = "🗑"; delBtn.className = "danger-ghost";
    fillBtn.disabled = false; delBtn.disabled = false;
    setStatus("Delete failed: " + e.message, "err");
  }
}

async function doUpdate(a, editUser, editPass, editTotp, editLabel, editForm, editSave, editCancel) {
  const usernameOrEmail = editUser.value.trim();
  const password        = editPass.value;
  const totpRaw         = editTotp.value.trim().toUpperCase().replace(/\s+/g, "") || null;
  const label           = editLabel.value.trim();

  if (!usernameOrEmail) { setStatus("Enter a username or email.", "err"); return; }
  if (!password)        { setStatus("A new password is required to save changes.", "err"); return; }
  const s = passwordStrength(password);
  if (s && s.score < 2) { setStatus("Password too weak — use at least 8 characters with mixed types.", "warn"); return; }

  editSave.disabled = true; editCancel.disabled = true;
  setStatus("Saving changes — approve Windows Hello…");
  try {
    // v2: label is plain text; TOTP secret goes to native host as separate field
    const r = await send({
      type: "update", credentialId: a.credentialId,
      usernameOrEmail, password,
      displayLabel: label,
      totpSecret:   totpRaw,
    });
    if (r?.accounts) renderAccounts(r.accounts);
    setStatus("Credential updated.", "ok");
  } catch (e) {
    editSave.disabled = false; editCancel.disabled = false;
    setStatus("Update failed: " + e.message, "err");
  }
}

// ---- Settings toggle handlers -----------------------------------------------

ui.settingsToggle.addEventListener("click", () => {
  ui.settingsPanel.classList.toggle("hidden");
  if (!ui.healthPanel.classList.contains("hidden")) ui.healthPanel.classList.add("hidden");
});

ui.healthToggle.addEventListener("click", () => {
  const opening = ui.healthPanel.classList.toggle("hidden");
  if (!opening) {
    // panel just became visible
    if (!ui.settingsPanel.classList.contains("hidden")) ui.settingsPanel.classList.add("hidden");
    refreshHealthPanel();
  }
});

ui.convenienceToggle.addEventListener("change", async () => {
  ui.convenienceToggle.disabled = true;
  try {
    if (ui.convenienceToggle.checked) {
      const granted = await chrome.permissions.request({ origins: ["https://*/*"] });
      if (!granted) {
        ui.convenienceToggle.checked = false;
        setStatus("Permission not granted — staying in Ultra Security Mode.", "warn");
        return;
      }
      const r = await send({ type: "updateSecuritySettings", patch: { convenienceEnabled: true } });
      sec = r.settings || sec; refreshSettingsUi();
      setStatus("Detector enabled. It cannot read saved-site metadata while locked.", "ok");
    } else {
      const r = await send({ type: "updateSecuritySettings", patch: { convenienceEnabled: false, site: { autoPrompt: false } } });
      sec = r.settings || sec; refreshSettingsUi();
      setStatus("Ultra Security Mode enabled.", "ok");
    }
  } catch (e) { setStatus("Settings error: " + e.message, "err"); }
  finally     { ui.convenienceToggle.disabled = false; }
});

ui.autoPromptToggle.addEventListener("change", async () => {
  try {
    const r = await send({ type: "updateSecuritySettings", patch: { site: { autoPrompt: ui.autoPromptToggle.checked } } });
    sec = r.settings || sec; refreshSettingsUi();
    setStatus(ui.autoPromptToggle.checked ? "Auto-unlock enabled for this site." : "Auto-unlock disabled for this site.", "ok");
  } catch (e) { setStatus("Settings error: " + e.message, "err"); }
});

ui.clipboardToggle.addEventListener("change", async () => {
  ui.clipboardToggle.disabled = true;
  try {
    const enabled = ui.clipboardToggle.checked === true;
    const r = await send({ type: "updateSecuritySettings", patch: { clipboardCopyEnabled: enabled } });
    sec = r.settings || sec; refreshSettingsUi();
    if (!ui.healthPanel.classList.contains("hidden")) refreshHealthPanel();
    setStatus(
      enabled
        ? "Clipboard copy enabled. Secrets still require Windows Hello and auto-clear."
        : "Clipboard copy disabled. Fill-only mode is active.",
      enabled ? "warn" : "ok");
  } catch (e) {
    ui.clipboardToggle.checked = sec.clipboardCopyEnabled === true;
    setStatus("Settings error: " + e.message, "err");
  } finally {
    ui.clipboardToggle.disabled = false;
  }
});

// ---- Timeout select ---------------------------------------------------------

ui.timeoutSelect.addEventListener("change", async () => {
  const minutes = parseInt(ui.timeoutSelect.value, 10);
  try {
    await send({ type: "setSessionTimeout", minutes });
    const labels = { 0: "immediately", 5: "5 min", 15: "15 min", 30: "30 min", 60: "1 hour" };
    setStatus(`Auto-lock set: ${labels[minutes] ?? minutes + " min"}.`, "ok");
  } catch (e) {
    setStatus("Timeout error: " + e.message, "err");
    // Reset select to a safe value if the new value was rejected
    ui.timeoutSelect.value = "15";
  }
});

// ---- Search -----------------------------------------------------------------

ui.searchInput.addEventListener("input", () => {
  const q = ui.searchInput.value.toLowerCase();
  for (const li of ui.accountList.children) {
    if (!q) { li.style.display = ""; continue; }
    const userText = li.querySelector(".acc-user")?.textContent?.toLowerCase() ?? "";
    const subText  = li.querySelector(".acc-sub")?.textContent?.toLowerCase()  ?? "";
    li.style.display = (userText.includes(q) || subText.includes(q)) ? "" : "none";
  }
});

// ---- Lock / unlock ----------------------------------------------------------

ui.unlockBtn.addEventListener("click", () => tryUnlock("Waiting for Windows Hello…"));

ui.lockBtn.addEventListener("click", async () => {
  try { await send({ type: "lock" }); } catch (_) {}
  setLocked(true);
  ui.accountList.innerHTML = "";
  currentAccounts = [];
  setStatus("Locked.");
});

// ---- Save form --------------------------------------------------------------

ui.toggleAdd.addEventListener("click", () => {
  const nowHidden = ui.addForm.classList.toggle("hidden");
  ui.toggleAdd.textContent = nowHidden ? "+ Save new credential" : "− Cancel";
  if (nowHidden) {
    ui.addPass.value = ""; ui.addLabel.value = ""; ui.addTotp.value = "";
    ui.strengthRow.classList.add("hidden");
  } else {
    ui.addUser.focus();
  }
});

ui.genPassBtn.addEventListener("click", () => {
  const pw = generatePassword(24);
  ui.addPass.type = "text"; ui.revealPassBtn.textContent = "🙈";
  ui.addPass.value = pw; updateStrength(pw);
  ui.addPass.focus();
  setStatus("Strong 24-character password generated.", "ok");
});

ui.revealPassBtn.addEventListener("click", () => {
  if (ui.addPass.type === "password") { ui.addPass.type = "text"; ui.revealPassBtn.textContent = "🙈"; }
  else                                { ui.addPass.type = "password"; ui.revealPassBtn.textContent = "👁"; }
});

ui.addPass.addEventListener("input", () => updateStrength(ui.addPass.value));

ui.saveBtn.addEventListener("click", async () => {
  const usernameOrEmail = ui.addUser.value.trim();
  const password        = ui.addPass.value;
  const totpRaw         = ui.addTotp.value.trim().toUpperCase().replace(/\s+/g, "") || null;
  const label           = ui.addLabel.value.trim();
  if (!usernameOrEmail || !password) {
    setStatus("Enter both a username/email and a password.", "err"); return;
  }
  const s = passwordStrength(password);
  if (s && s.score < 2) {
    setStatus("Password is too weak — use at least 8 characters with mixed types.", "warn"); return;
  }
  ui.saveBtn.disabled = true;
  setStatus("Waiting for Windows Hello fingerprint / PIN…");
  try {
    // v2: TOTP stored in native host payload, not encoded in label
    await send({ type: "add", usernameOrEmail, password, displayLabel: label, totpSecret: totpRaw });
    ui.addPass.value = ""; ui.addLabel.value = ""; ui.addTotp.value = "";
    ui.strengthRow.classList.add("hidden");
    setLocked(false);
    const r = await send({ type: "listFill" });
    renderAccounts(r.accounts);
    ui.addForm.classList.add("hidden");
    ui.toggleAdd.textContent = "+ Save new credential";
    setStatus("Saved. Origin, label, timestamps, and 2FA secret are encrypted in the vault.", "ok");
  } catch (e) {
    setStatus("Save failed: " + e.message, "err");
  } finally {
    ui.saveBtn.disabled = false;
  }
});

// ---- Windows Hello availability (defensive) ---------------------------------
//
// The native host returns one of these canonical values:
//   Available | DeviceNotPresent | NotConfigured | DisabledByPolicy | Unavailable | Unknown
// We normalize case-insensitively and classify into three buckets so the popup
// never shows a false "not ready: available" alert (the original casing bug),
// and never crashes on a null/empty/unexpected value.
function helloAvailabilityState(raw) {
  const value = (raw == null ? "" : String(raw));
  const norm  = value.trim().toLowerCase();

  if (norm === "available")
    return { kind: "usable", raw: value || "Available" };

  // Definite, known "cannot use right now" states.
  if (norm === "devicenotpresent" || norm === "notconfigured" ||
      norm === "notconfiguredforuser" || norm === "disabledbypolicy" ||
      norm === "unavailable" || norm === "devicebusy")
    return { kind: "unusable", raw: value };

  // Empty, "unknown", or anything we don't recognize → warn but allow attempt.
  return { kind: "unknown", raw: value || "(empty)" };
}

// ---- Init -------------------------------------------------------------------

async function init() {
  try {
    // Integrity first — this route is exempt from the integrity gate so we can
    // always TELL the user what failed instead of failing opaquely.
    const ig = await send({ type: "getIntegrityStatus" }).catch(() => null);
    const integrityFailed = ig?.integrity?.status === "failed";

    const [c, s] = await Promise.all([
      send({ type: "getContext" }),
      send({ type: "status" }),
    ]);

    ctx = c || {};
    ui.origin.textContent = c?.origin || "(no login page detected)";
    ui.alerts.innerHTML   = "";

    if (integrityFailed) {
      const names = (ig.integrity.failingFileNames || []).join(", ") || "unknown file(s)";
      addAlert(
        "⛔  Extension integrity check failed (" + names + "). " +
        "Run tools/update-extension-hashes.ps1 after legitimate source changes, then reload. " +
        "Secret operations are blocked until integrity passes.", "danger");
    }

    const [secRes, toRes] = await Promise.all([
      send({ type: "getSecuritySettings" }),
      send({ type: "getSessionTimeout" }),
    ]);
    sec = secRes?.settings || sec;
    refreshSettingsUi();
    if (toRes?.sessionTimeoutMinutes !== undefined && toRes.sessionTimeoutMinutes >= 0) {
      ui.timeoutSelect.value = String(toRes.sessionTimeoutMinutes);
    }

    if (c?.isHttp)        addAlert("⛔  HTTP page — save and fill are blocked.", "danger");
    if (c?.isIdn)         addAlert("⛔  Punycode / IDN domain — blocked to prevent lookalike-domain theft.", "danger");
    if (c?.isHighRisk)    addAlert("⚠  High-risk site — auto-unlock is disabled; manual fill still works.", "warn");
    if (c?.blockedReason) addAlert("⚠  Fill blocked: " + c.blockedReason + ".", "warn");
    if (c?.origin && !c?.hasLogin && !c?.blockedReason)
                           addAlert("ℹ  No login form detected on this page.", "info");

    if (s?.ok && s.result) {
      const state = helloAvailabilityState(s.result.presenceAvailability);
      if (state.kind === "unusable") {
        addAlert(`⛔  Windows Hello not ready: ${state.raw}. Set up a PIN or biometric in Windows Settings.`, "danger");
      } else if (state.kind === "unknown") {
        // Could not determine availability — warn, but do not hard-block the attempt.
        addAlert(`⚠  Windows Hello status could not be determined (${state.raw}). Unlock may still work; if not, check Windows Hello in Settings.`, "warn");
      }
      // state.kind === "usable" → no alert (this is the case that was wrongly firing before)
      if (!s.result.exists)
        setStatus("No vault yet — saving your first credential creates it.");
    }

    const sessionRes = await send({ type: "checkSession" }).catch(() => null);
    if (sessionRes?.valid) {
      setLocked(false);
      const listRes = await send({ type: "listFill" }).catch(() => null);
      if (listRes?.accounts) renderAccounts(listRes.accounts);
      const timeInfo = await timeoutStatusText();
      setStatus(`Vault unlocked. Fresh Hello per fill. ${timeInfo}`, "ok");
      return;
    }

    setLocked(true);

    if (sec.convenienceEnabled && sec.site?.autoPrompt &&
        c?.origin && !c?.isHttp && !c?.isIdn && !sec?.isHighRisk) {
      await tryUnlock("Login form detected — unlocking with Windows Hello…");
    }
  } catch (e) {
    ui.origin.textContent = "—";
    setStatus("Error: " + e.message, "err");
  }
}

init();
